export function validate(data){
 if(!data||!Array.isArray(data.deals)||!Number.isFinite(Date.parse(data.updatedAt)))throw Error('Invalid dataset');
 const ids=new Set();for(const d of data.deals){if(!/^[a-z0-9-]+$/.test(d.id)||ids.has(d.id))throw Error('Invalid or duplicate ID');ids.add(d.id);for(const key of ['restaurant','address','town','title','priceLabel','timeLabel','terms','lastChecked'])if(typeof d[key]!=='string'||!d[key])throw Error('Missing '+key);if(!['Ashburn','Leesburg','Sterling','Purcellville','Middleburg','Brambleton','South Riding','Broadlands','Lansdowne','Hamilton','Round Hill','Lovettsville','Aldie'].includes(d.town))throw Error('Review Loudoun location');if(!Array.isArray(d.days)||!d.days.length||d.days.some(n=>!Number.isInteger(n)||n<0||n>6))throw Error('Invalid days');if(d.price!==null&&(!Number.isFinite(d.price)||d.price<0))throw Error('Invalid price');if(new URL(d.sourceUrl).protocol!=='https:')throw Error('Invalid source');if(!['active','needs-review','expired','withdrawn'].includes(d.status))throw Error('Invalid status');if(!Number.isFinite(Date.parse(d.lastChecked)))throw Error('Invalid check date');if(d.validThrough&&!Number.isFinite(Date.parse(d.validThrough)))throw Error('Invalid expiration');for(const key of ['start','end'])if(d[key]&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(d[key]))throw Error('Invalid time');}return data;
}
export function easternDate(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function activeDeals(data,now=new Date()){const date=easternDate(now);return data.deals.filter(d=>d.status==='active'&&(!d.validThrough||d.validThrough>=date));}
export function filterDeals(deals,{day='all',town='all',kind='all',query=''}={}){return deals.filter(d=>(day==='all'||d.days.includes(Number(day)))&&(town==='all'||d.town===town)&&(kind==='all'||(kind==='10'?d.price!==null&&d.price<=10:d.category===kind))&&`${d.title} ${d.restaurant} ${d.town} ${d.terms}`.toLowerCase().includes(query.toLowerCase()));}

export function googleMapsUrl(deal){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(`${deal.restaurant}, ${deal.address}`);}
